"""Differential fuzz: generate valid-by-construction requests, compute expected
serialization independently, compare with the bridge output."""
import json, random, sys
from ipaddress import IPv6Address
sys.path.insert(0, '/workspace/tmp')
from harness import run

ROUTES = {"https://demo.test":"rack-a","https://alt.test:8443":"rack-a","http://demo.test":"rack-b",
          "http://[2001:db8::1]:8080":"rack-c","https://[::ffff:192.0.2.1]":"rack-d",
          "http://192.0.2.1":"rack-e","https://x.test:1":"rack-f","http://y.test:65535":"rack-g"}
KEYS = list(ROUTES)

SINGLE = ['x-a','user-agent','etag','if-range','content-type','accept-ranges','x-b-c']
MULTI = ['accept','accept-encoding','cache-control','if-match','if-none-match','pragma','vary','x-list-a','x-list-q']
VALS = ['1','*/*','a=1','x y','\u00e9','"v1"','no-cache','bytes=0-1','v'*3,'a\tb']

def canon_authority(value, scheme):
    """Independent canonicalizer for the generator's authority pool."""
    default = 80 if scheme == 'http' else 443
    if value.startswith('['):
        i = value.index(']')
        host = '[' + IPv6Address(value[1:i]).compressed + ']'
        port = value[i+2:] if len(value) > i+1 else None
    else:
        host, _, port = value.partition(':')
        port = port or None
        host = host.lower()
    if port is not None:
        p = int(port)
        if p != default:
            host = host + ':' + str(p)
    return host

def gen_request(rng):
    key = rng.choice(KEYS)
    scheme, authority = key.split('://', 1)
    method = rng.choice(['GET','HEAD','POST','PUT','PATCH','DELETE','OPTIONS'])
    path = rng.choice(['/','/a','/a/b','/a%2Fb?x=1&x=2','/q?a=1&b=2','/x-y_z~','/*','/%ff/%FF'])
    if path == '*' and method != 'OPTIONS':
        path = '/'
    fields = [[':method', method],[':scheme',scheme]]
    use_host = rng.random() < 0.3
    if use_host:
        fields.append([':path', path])
    else:
        fields.append([':authority', authority]); fields.append([':path', path])
    regular = []
    for n in rng.sample(SINGLE, rng.randint(0,3)):
        regular.append([n, rng.choice(VALS)])
    for n in rng.sample(MULTI, rng.randint(0,3)):
        for _ in range(rng.randint(1,3)):
            regular.append([n, rng.choice(VALS)])
    ncookies = rng.randint(0,3)
    cookies = [['cookie', rng.choice(['a=1','b=2','sid=xyz','theme=dark'])] for _ in range(ncookies)]
    if use_host:
        regular.append(['host', authority])
    regular += cookies
    if rng.random() < 0.3:
        regular.append(['te','trailers'])
    rng.shuffle(regular)
    fields += regular
    body = bytes(rng.randrange(256) for _ in range(rng.choice([0,0,1,3,17,255,256,1000])))
    has_cl = rng.random() < 0.6
    if has_cl:
        cl = str(len(body))
        if rng.random() < 0.3: cl = '0'*(rng.randint(1,3)) + cl
        if rng.random() < 0.3 and len(body): cl = cl + ', ' + '0'*(rng.randint(0,2)) + str(len(body))
        pos = rng.randint(0, len(fields))
        fields.insert(pos, ['content-length', cl])
    trailers = None
    if rng.random() < 0.4:
        trailers = []
        for _ in range(rng.randint(0,4)):
            trailers.append([rng.choice(['x-audit-a','x-audit-b','x-audit-c']), rng.choice(VALS)])
    return dict(scheme=scheme, authority=authority, method=method, path=path, fields=fields,
                body=body, trailers=trailers, use_host=use_host, cookies=[c[1] for c in cookies])

def expected_raw(req):
    out = bytearray()
    out += req['method'].encode() + b' ' + req['path'].encode() + b' HTTP/1.1\r\n'
    out += b'host: ' + canon_authority(req['authority'], req['scheme']).encode() + b'\r\n'
    emitted = []
    cookie_slot = None
    for name, value in req['fields']:
        if name.startswith(':'): continue
        if name in ('host','content-length','te'): continue
        if name == 'cookie':
            if cookie_slot is None:
                cookie_slot = len(emitted); emitted.append(None)
            continue
        emitted.append((name, value))
    if cookie_slot is not None:
        emitted[cookie_slot] = ('cookie', '; '.join(req['cookies']))
    for name, value in emitted:
        out += name.encode() + b': ' + value.encode('latin-1') + b'\r\n'
    body = req['body']
    if req['trailers'] is None:
        out += b'content-length: ' + str(len(body)).encode() + b'\r\n\r\n' + body
    else:
        out += b'transfer-encoding: chunked\r\n'
        names = []
        for n, v in req['trailers']:
            if n not in names: names.append(n)
        if names:
            out += b'trailer: ' + ', '.join(names).encode() + b'\r\n'
        out += b'\r\n'
        if body:
            out += ('%x' % len(body)).encode() + b'\r\n' + body + b'\r\n'
        out += b'0\r\n'
        for n, v in req['trailers']:
            out += n.encode() + b': ' + v.encode('latin-1') + b'\r\n'
        out += b'\r\n'
    return bytes(out)

rng = random.Random(int(sys.argv[1]) if len(sys.argv) > 1 else 1)
bad = 0
for it in range(200):
    events = []
    expect = {}
    sids = list(range(0, 4*rng.randint(1,6), 4))
    reqs = {}
    for sid in sids:
        reqs[sid] = gen_request(rng)
    # emit events in random interleaving, splitting data and headers
    pending = {sid: [] for sid in sids}
    for sid, req in reqs.items():
        pending[sid].append({'sid':sid,'type':'headers','fields':req['fields']})
        b = req['body']
        while b:
            k = min(len(b), rng.randint(1, len(b)))
            pending[sid].append({'sid':sid,'type':'data','hex':b[:k].hex()}); b = b[k:]
        if rng.random() < 0.3:
            pending[sid].append({'sid':sid,'type':'unknown','frame_type':rng.choice([33,64,1000]),'hex':'00ff'})
        if req['trailers'] is not None:
            pending[sid].append({'sid':sid,'type':'headers','fields':req['trailers']})
        pending[sid].append({'sid':sid,'type':'fin'})
    order = []
    keys = list(pending)
    rng.shuffle(keys)
    while keys:
        k = rng.choice(keys)
        order.append(pending[k].pop(0))
        if not pending[k]: keys.remove(k)
    r = run({'routes': ROUTES, 'events': order})
    pipes = {k: bytearray() for k in set(ROUTES.values())}
    for rec in r['streams']:
        sid = rec['sid']
        req = reqs[sid]
        exp_raw = expected_raw(req)
        origin = ROUTES[req['scheme'] + '://' + canon_authority(req['authority'], req['scheme'])]
        if rec['status'] != 'forwarded':
            bad += 1; print('iter',it,'sid',sid,'status',rec['status'], json.dumps(req['fields'])[:300]); continue
        if rec['origin'] != origin:
            bad += 1; print('iter',it,'sid',sid,'origin',rec['origin'],origin)
        if rec['cache_key'] != [req['method'], req['scheme'], canon_authority(req['authority'], req['scheme']), req['path']]:
            bad += 1; print('iter',it,'sid',sid,'cache_key',rec['cache_key'])
        got = bytes.fromhex(r['origins'][origin])[rec['offset']:rec['offset']+rec['length']]
        if got != exp_raw:
            bad += 1
            print('iter',it,'sid',sid,'RAW MISMATCH')
            print(' got ', got)
            print(' want', exp_raw)
        if rec['length'] != len(exp_raw): bad += 1; print('length mismatch')
        # commit_at must equal the fin index
        finidx = max(i for i,e in enumerate(order) if e['sid']==sid and e['type']=='fin')
        if rec['commit_at'] != finidx: bad += 1; print('commit_at mismatch', rec['commit_at'], finidx)
    if bad > 3: break
print('done bad =', bad)
EOF
